SITE = '/home/riomus/group-learning/.venv/lib/python3.13/site-packages'

import base64,csv,email.parser,hashlib,io,json,stat,sys
from pathlib import Path
site=Path(SITE)
actual={str(p) for p in site.glob('*.dist-info/RECORD')}
assert actual==set(EXPECTED_RECORDS), 'installed RECORD inventory differs from original196'
owners={p:[] for p in TARGETS};profiles={}
def read_regular(p):
 assert p.is_absolute() and p.resolve()==p and stat.S_ISREG(p.lstat().st_mode) and not p.is_symlink()
 raw=p.read_bytes();assert len(raw)<=16777216
 return raw
for filename,expected in sorted(EXPECTED_RECORDS.items()):
 record=Path(filename);raw=read_regular(record);assert hashlib.sha256(raw).hexdigest()==expected, filename
 found=[];metadata_rows=[]
 for row in csv.reader(io.StringIO(raw.decode('utf-8'))):
  assert len(row)==3
  name,encoded,size=row
  lexical=site/name
  if name==record.parent.name+'/METADATA':metadata_rows.append(row)
  # Normal pip RECORD entries may contain ../ for console scripts. No such target is read.
  target=str(lexical.resolve())
  if target not in TARGETS:continue
  assert encoded.startswith('sha256=') and size.isascii() and size.isdigit()
  digest=base64.urlsafe_b64decode(encoded[7:]+'='*((-len(encoded[7:]))%4)).hex()
  assert digest==TARGETS[target], 'selected original byte hash differs from RECORD row'
  assert Path(target).is_relative_to(site) and Path(target).resolve()==Path(target)
  assert stat.S_ISREG(Path(target).lstat().st_mode) and not Path(target).is_symlink()
  assert Path(target).stat().st_size==int(size)
  fact={'file':target,'record_relative_path':name,'sha256':digest,'bytes':int(size),'record':filename,'record_sha256':expected}
  owners[target].append(fact);found.append(fact)
 if not found:continue
 assert len(metadata_rows)==1
 name,encoded,size=metadata_rows[0];assert encoded.startswith('sha256=') and size.isdigit()
 metadata=read_regular(site/name);digest=base64.urlsafe_b64decode(encoded[7:]+'='*((-len(encoded[7:]))%4)).hex()
 assert hashlib.sha256(metadata).hexdigest()==digest and len(metadata)==int(size)
 parsed=email.parser.BytesParser().parsebytes(metadata)
 assert len(parsed.get_all('Name',[]))==len(parsed.get_all('Version',[]))==1
 profiles[filename]={'record_sha256':expected,'metadata':{'path':str(site/name),'sha256':digest,'bytes':len(metadata)},'name':parsed['Name'],'version':parsed['Version'],'selected_members':found}
assert all(len(v)==1 for v in owners.values()), 'selected target must have one original RECORD owner'
for p,h in MODEL_SOURCES.items():assert hashlib.sha256(read_regular(Path(p))).hexdigest()==h
result={'schema':'connected-original-record-ownership-source-audit-v1','records':len(EXPECTED_RECORDS),'selected_members':len(TARGETS),'selected_native_members':len(TARGETS)-len(MODEL_SOURCES),'current_model_sources_sha_pass':len(MODEL_SOURCES),'profiles':profiles,'unique_owner_pass':True,'original_record_sha_and_metadata_row_pass':True,'native_file_bytes_hashed':False,'native_modules_imported':False,'native_qualification':False,'product_go':False}
sys.stdout.write(json.dumps(result,indent=2,sort_keys=True)+'\n')
